{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 p50ms FROM abnormal_traces WHERE (service_name='search') OR (service_name='frontend' AND span_name='search.Search/Nearby') GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, attr_status_code, count(*), quantile_cont(duration,0.5)/1e6 FROM normal_traces WHERE (service_name='search') OR (service_name='frontend' AND span_name='search.Search/Nearby') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Search emits no spans in the abnormal window (3381 normal); frontend search.Search/Nearby calls all error, about 0.01 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name='search-769f8b94b6-bmsc9' AND metric='k8s.container.restarts' ORDER BY time",
          "claim": "Search pod search-769f8b94b6-bmsc9 restart counter climbs from 2 to 6 during the abnormal window; normal period shows 0."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY ALL",
          "claim": "All 1159 frontend /hotels server spans return HTTP 500 with Error status, after search calls fail."
        }
      ]
    }
  ]
}
```

